"""Immutable, validated semantic observations; this schema never contains pixels.

Coordinates are normalized to the whole image. Confidence is an observation
score in [0, 1], not a guarantee that an observation is correct. JSON helpers
reject unknown fields and coercions so malformed cache/input data fails early.
"""

from __future__ import annotations

from dataclasses import dataclass
import math
import re
from typing import Any


def _number(value: Any, name: str) -> float:
    if isinstance(value, bool) or not isinstance(value, (int, float)):
        raise ValueError(f"{name} must be a finite number")
    try:
        result = float(value)
    except (ValueError, OverflowError) as exc:
        raise ValueError(f"{name} must be a finite number") from exc
    if not math.isfinite(result):
        raise ValueError(f"{name} must be a finite number")
    return result


def _confidence(value: Any, name: str = "confidence") -> float:
    result = _number(value, name)
    if not 0 <= result <= 1:
        raise ValueError(f"{name} must be in [0, 1]")
    return result


def _string(value: Any, name: str, *, empty: bool = False) -> str:
    if not isinstance(value, str) or (not empty and not value.strip()):
        raise ValueError(f"{name} must be {'a' if empty else 'a nonempty'} string")
    if any(0xD800 <= ord(char) <= 0xDFFF for char in value):
        raise ValueError(f"{name} must not contain unpaired Unicode surrogates")
    return value


def _identifier(value: Any, name: str, prefix: str = "[OT]") -> str:
    if not isinstance(value, str) or re.fullmatch(prefix + r"[1-9][0-9]*", value) is None:
        raise ValueError(f"{name} must match {prefix}[1-9][0-9]*")
    return value


def _collection(value: Any, item_type: type, name: str) -> tuple:
    if not isinstance(value, (tuple, list)):
        raise ValueError(f"{name} must be a tuple or list")
    if any(not isinstance(item, item_type) for item in value):
        raise ValueError(f"{name} must contain only {item_type.__name__} values")
    return tuple(value)


@dataclass(frozen=True)
class BBox:
    """Normalized x1,y1,x2,y2; zero-area boxes are legal observations."""

    x1: float
    y1: float
    x2: float
    y2: float

    def __post_init__(self) -> None:
        for name in ("x1", "y1", "x2", "y2"):
            object.__setattr__(self, name, _confidence(getattr(self, name), name))
        if self.x1 > self.x2 or self.y1 > self.y2:
            raise ValueError("bbox coordinates must satisfy x1 <= x2 and y1 <= y2")


@dataclass(frozen=True)
class Attribute:
    name: str
    value: str
    confidence: float

    def __post_init__(self) -> None:
        _string(self.name, "attribute.name")
        _string(self.value, "attribute.value", empty=True)
        object.__setattr__(self, "confidence", _confidence(self.confidence))


@dataclass(frozen=True)
class DetectedObject:
    id: str
    label: str
    bbox: BBox
    confidence: float
    attributes: tuple[Attribute, ...] = ()

    def __post_init__(self) -> None:
        _identifier(self.id, "object.id", "O")
        _string(self.label, "object.label")
        if not isinstance(self.bbox, BBox):
            raise ValueError("object.bbox must be a BBox")
        object.__setattr__(self, "confidence", _confidence(self.confidence))
        object.__setattr__(
            self, "attributes", _collection(self.attributes, Attribute, "attributes")
        )


@dataclass(frozen=True)
class DetectedText:
    id: str
    text: str
    bbox: BBox
    confidence: float
    language: str | None = None

    def __post_init__(self) -> None:
        _identifier(self.id, "text.id", "T")
        _string(self.text, "text.text", empty=True)
        if not isinstance(self.bbox, BBox):
            raise ValueError("text.bbox must be a BBox")
        object.__setattr__(self, "confidence", _confidence(self.confidence))
        if self.language is not None:
            _string(self.language, "text.language")


@dataclass(frozen=True)
class Relation:
    source: str
    predicate: str
    target: str
    confidence: float

    def __post_init__(self) -> None:
        _identifier(self.source, "relation.source", "O")
        _string(self.predicate, "relation.predicate")
        _identifier(self.target, "relation.target", "O")
        object.__setattr__(self, "confidence", _confidence(self.confidence))


@dataclass(frozen=True)
class SceneDescription:
    text: str
    confidence: float

    def __post_init__(self) -> None:
        _string(self.text, "description.text", empty=True)
        object.__setattr__(self, "confidence", _confidence(self.confidence))


@dataclass(frozen=True)
class VisualScene:
    width: int
    height: int
    objects: tuple[DetectedObject, ...] = ()
    texts: tuple[DetectedText, ...] = ()
    relations: tuple[Relation, ...] = ()
    caption: SceneDescription | None = None
    tags: tuple[SceneDescription, ...] = ()
    query: str | None = None

    def __post_init__(self) -> None:
        for name in ("width", "height"):
            value = getattr(self, name)
            if isinstance(value, bool) or not isinstance(value, int) or value <= 0:
                raise ValueError(f"{name} must be a positive integer")
        for name, item_type in (
            ("objects", DetectedObject),
            ("texts", DetectedText),
            ("relations", Relation),
            ("tags", SceneDescription),
        ):
            object.__setattr__(self, name, _collection(getattr(self, name), item_type, name))
        if self.caption is not None and not isinstance(self.caption, SceneDescription):
            raise ValueError("caption must be a SceneDescription or None")
        if self.query is not None:
            _string(self.query, "query", empty=True)
        identifiers = [item.id for item in (*self.objects, *self.texts)]
        if len(set(identifiers)) != len(identifiers):
            raise ValueError("scene contains duplicate object/text IDs")
        known = set(identifiers)
        for relation in self.relations:
            missing = {relation.source, relation.target} - known
            if missing:
                raise ValueError(f"relation references missing IDs: {', '.join(sorted(missing))}")


def _record(data: Any, required: set[str], optional: set[str], path: str) -> dict:
    if not isinstance(data, dict):
        raise ValueError(f"{path} must be a JSON object")
    missing = required - data.keys()
    unknown = data.keys() - required - optional
    if missing:
        raise ValueError(f"{path} is missing fields: {', '.join(sorted(missing))}")
    if unknown:
        raise ValueError(f"{path} has unknown fields: {', '.join(sorted(map(str, unknown)))}")
    return data


def _array(data: Any, path: str) -> list:
    if not isinstance(data, list):
        raise ValueError(f"{path} must be a JSON array")
    return data


def _box(data: Any, path: str) -> BBox:
    values = _array(data, path)
    if len(values) != 4:
        raise ValueError(f"{path} must contain exactly four coordinates")
    return BBox(*values)


def _description(data: Any, path: str) -> SceneDescription:
    row = _record(data, {"text", "confidence"}, set(), path)
    return SceneDescription(row["text"], row["confidence"])


def scene_from_dict(data: dict[str, Any]) -> VisualScene:
    """Read strict JSON-ready scene data; bbox values are four-element arrays.

    Only width and height are required at scene level. Optional collections
    default to empty; caption/query default to null. Nested observations require
    their semantic fields and confidence; object attributes and OCR language
    are optional. Unknown keys are errors at every level.
    """
    row = _record(
        data,
        {"width", "height"},
        {"objects", "texts", "relations", "caption", "tags", "query"},
        "scene",
    )
    objects = []
    for index, obj in enumerate(_array(row.get("objects", []), "scene.objects")):
        path = f"scene.objects[{index}]"
        obj = _record(obj, {"id", "label", "bbox", "confidence"}, {"attributes"}, path)
        attributes = []
        for attr_index, attr in enumerate(_array(obj.get("attributes", []), f"{path}.attributes")):
            attr = _record(
                attr, {"name", "value", "confidence"}, set(), f"{path}.attributes[{attr_index}]"
            )
            attributes.append(Attribute(**attr))
        objects.append(
            DetectedObject(
                obj["id"],
                obj["label"],
                _box(obj["bbox"], f"{path}.bbox"),
                obj["confidence"],
                tuple(attributes),
            )
        )
    texts = []
    for index, item in enumerate(_array(row.get("texts", []), "scene.texts")):
        path = f"scene.texts[{index}]"
        item = _record(item, {"id", "text", "bbox", "confidence"}, {"language"}, path)
        texts.append(
            DetectedText(
                item["id"],
                item["text"],
                _box(item["bbox"], f"{path}.bbox"),
                item["confidence"],
                item.get("language"),
            )
        )
    relations = []
    for index, relation in enumerate(_array(row.get("relations", []), "scene.relations")):
        relation = _record(
            relation,
            {"source", "predicate", "target", "confidence"},
            set(),
            f"scene.relations[{index}]",
        )
        relations.append(Relation(**relation))
    tags = tuple(
        _description(tag, f"scene.tags[{index}]")
        for index, tag in enumerate(_array(row.get("tags", []), "scene.tags"))
    )
    caption = (
        _description(row["caption"], "scene.caption") if row.get("caption") is not None else None
    )
    return VisualScene(
        row["width"],
        row["height"],
        tuple(objects),
        tuple(texts),
        tuple(relations),
        caption,
        tags,
        row.get("query"),
    )


def scene_to_dict(scene: VisualScene) -> dict[str, Any]:
    """Return a fresh JSON-compatible value preserving all observations exactly."""
    if not isinstance(scene, VisualScene):
        raise ValueError("scene must be a VisualScene")

    def bbox(box: BBox) -> list[float]:
        return [box.x1, box.y1, box.x2, box.y2]

    def description(item: SceneDescription) -> dict[str, Any]:
        return {"text": item.text, "confidence": item.confidence}

    return {
        "width": scene.width,
        "height": scene.height,
        "objects": [
            {
                "id": obj.id,
                "label": obj.label,
                "bbox": bbox(obj.bbox),
                "confidence": obj.confidence,
                "attributes": [
                    {"name": attr.name, "value": attr.value, "confidence": attr.confidence}
                    for attr in obj.attributes
                ],
            }
            for obj in scene.objects
        ],
        "texts": [
            {
                "id": item.id,
                "text": item.text,
                "bbox": bbox(item.bbox),
                "confidence": item.confidence,
                "language": item.language,
            }
            for item in scene.texts
        ],
        "relations": [
            {
                "source": rel.source,
                "predicate": rel.predicate,
                "target": rel.target,
                "confidence": rel.confidence,
            }
            for rel in scene.relations
        ],
        "caption": description(scene.caption) if scene.caption is not None else None,
        "tags": [description(tag) for tag in scene.tags],
        "query": scene.query,
    }
